 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find monochrome template (the object repeated in the output).
    colors = {}
    for r in range(h):
        for c in range(w):
            if g[r][c]: colors.setdefault(g[r][c], []).append((r,c))
    template_color = max(colors, key=lambda x: len(colors[x]))
    pts = colors[template_color]
    # Key is the other repeated bar; collapse its repeated cells to ordered colors.
    other = [(r,c) for col,ps in colors.items() if col != template_color for r,c in ps]
    if not other: return g
    rr=[r for r,c in other]; cc=[c for r,c in other]
    if len(set(rr)) <= len(set(cc)):
        # horizontal key (colors sequence left-to-right); remove row repetition
        line = min(rr)
        palette=[]
        for c in sorted(set(c for r,c in other)):
            v=next(g[r][c] for r in range(h) if g[r][c])
            if not palette or v != palette[-1]: palette.append(v)
    else:
        # vertical key (colors sequence top-to-bottom across columns)
        palette=[]
        for c in sorted(set(c for r,c in other)):
            vals=[g[r][c] for r in sorted(set(r for r,c2 in other if c2==c))]
            v=vals[0]
            if not palette or v != palette[-1]: palette.append(v)
    top=min(r for r,c in pts); bottom=max(r for r,c in pts)
    left=min(c for r,c in pts); shape=[(r-top,c-left) for r,c in pts]
    step=bottom-top+1
    # Stack the template copies centered on the original template's row band.
    start=top-(palette.index(template_color))*step if template_color in palette else top-(len(palette)//2)*step
    for i,col in enumerate(palette):
        for dr,dc in shape:
            r=start+i*step+dr; c=left+dc
            if 0<=r<h and 0<=c<w: g[r][c]=col
    return g

if __name__ == '__main__':
    pass
